2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"time"
8	)
9	
10	// HookHost identifies which host format produced a copilot-compatible hook payload.
11	type HookHost string
12	
13	const (
14		HostUnknown    HookHost = "unknown"
15		HostCopilotCLI HookHost = "copilot-cli"
16		HostVSCode     HookHost = "vscode"
17	)
18	
19	// VS Code hookEventName values (from official VS Code docs).
20	// See: https://code.visualstudio.com/docs/copilot/customization/hooks
21	const (
22		VSCodeEventSessionStart     = "SessionStart"
23		VSCodeEventUserPromptSubmit = "UserPromptSubmit"
24		VSCodeEventStop             = "Stop"
25		VSCodeEventPreToolUse       = "PreToolUse"
26		VSCodeEventPostToolUse      = "PostToolUse"
27		VSCodeEventPreCompact       = "PreCompact"
28		VSCodeEventSubagentStart    = "SubagentStart"
29		VSCodeEventSubagentStop     = "SubagentStop"
30	)
31	
32	// vsCodeEventToHookNames maps each VS Code hookEventName to the CLI hook name(s)
33	// that are allowed to carry that event. "Stop" maps to both agent-stop and
34	// session-end because VS Code uses a single Stop event where Copilot CLI
35	// distinguishes the two.
36	var vsCodeEventToHookNames = map[string][]string{
37		VSCodeEventUserPromptSubmit: {HookNameUserPromptSubmitted},
38		VSCodeEventSessionStart:     {HookNameSessionStart},
39		VSCodeEventStop:             {HookNameAgentStop, HookNameSessionEnd},
40		VSCodeEventSubagentStop:     {HookNameSubagentStop},
41		VSCodeEventPreToolUse:       {HookNamePreToolUse},
42		VSCodeEventPostToolUse:      {HookNamePostToolUse},
43		VSCodeEventPreCompact:       {},
44		VSCodeEventSubagentStart:    {},
45	}
46	
47	type hookEnvelope struct {
48		Host           HookHost
49		SessionID      string
50		Prompt         string
51		TranscriptPath string
52		HookEventName  string
53		Source         string
54		InitialPrompt  string
55		StopReason     string
56		Reason         string
57		Timestamp      time.Time
58	}
59	
60	func parseHookEnvelope(data []byte) (*hookEnvelope, error) {
61		if len(data) == 0 {
62			return nil, errors.New("empty hook input")
63		}
64	
65		var raw map[string]json.RawMessage
66		if err := json.Unmarshal(data, &raw); err != nil {
67			return nil, fmt.Errorf("failed to parse hook input: %w", err)
68		}
69	
70		env := &hookEnvelope{
71			Host:           detectHookHost(raw),
72			SessionID:      firstString(raw, "sessionId"),
73			Prompt:         firstString(raw, "prompt"),
74			TranscriptPath: firstString(raw, "transcriptPath", "transcript_path"),
75			HookEventName:  firstString(raw, "hookEventName"),
76			Source:         firstString(raw, "source"),
77			InitialPrompt:  firstString(raw, "initialPrompt"),
78			StopReason:     firstString(raw, "stopReason"),
79			Reason:         firstString(raw, "reason"),
80		}
81	
82		ts, err := parseTimestamp(raw["timestamp"])
83		if err != nil {
84			return nil, fmt.Errorf("failed to parse hook input: %w", err)
85		}
86		env.Timestamp = ts
87	
88		if env.Timestamp.IsZero() {
89			env.Timestamp = time.Now()
90		}
91	
92		return env, nil
93	}
94	
95	func detectHookHost(raw map[string]json.RawMessage) HookHost {
96		if _, ok := raw["hookEventName"]; ok {
97			return HostVSCode
98		}
99		if _, ok := raw["transcript_path"]; ok {
100			return HostVSCode
101		}
102		if isJSONString(raw["timestamp"]) {
103			return HostVSCode
104		}
105		if _, ok := raw["transcriptPath"]; ok {
106			return HostCopilotCLI
107		}
108		if isJSONNumber(raw["timestamp"]) {
109			return HostCopilotCLI
110		}
111		return HostUnknown
112	}
113	
114	func firstString(raw map[string]json.RawMessage, keys ...string) string {
115		for _, key := range keys {
116			value, ok := raw[key]
117			if !ok {
118				continue
119			}
120			var s string
121			if err := json.Unmarshal(value, &s); err == nil {
122				return s
123			}
124		}
125		return ""
126	}
127	
128	func parseTimestamp(raw json.RawMessage) (time.Time, error) {
129		if len(raw) == 0 || string(raw) == "null" {
130			return time.Time{}, nil
131		}
132	
133		var millis int64
134		if err := json.Unmarshal(raw, &millis); err == nil {
135			if millis == 0 {
136				return time.Time{}, nil // Treat epoch as missing — triggers time.Now() fallback.
137			}
138			return time.UnixMilli(millis), nil
139		}
140	
141		var ts string
142		if err := json.Unmarshal(raw, &ts); err != nil {
143			return time.Time{}, fmt.Errorf("unmarshal timestamp string: %w", err)
144		}
145	
146		parsed, err := time.Parse(time.RFC3339Nano, ts)
147		if err != nil {
148			return time.Time{}, fmt.Errorf("parse timestamp %q: %w", ts, err)
149		}
150		return parsed, nil
151	}
152	
153	func isJSONString(raw json.RawMessage) bool {
154		if len(raw) == 0 || raw[0] != '"' {
155			return false
156		}
157		var s string
158		return json.Unmarshal(raw, &s) == nil
159	}
160	
161	func isJSONNumber(raw json.RawMessage) bool {
162		if len(raw) == 0 || raw[0] == 'n' {
163			return false
164		}
165		var n int64
166		return json.Unmarshal(raw, &n) == nil
167	}
