169	// validateVSCodeEvent checks whether the hookEventName is consistent with the
170	// CLI hook subcommand that was invoked. Returns true if the event should be
171	// processed, false if it should be silently skipped (mismatch or unknown event).
172	func validateVSCodeEvent(hookEventName, hookName string) bool {
173		allowedHooks, known := vsCodeEventToHookNames[hookEventName]
174		if !known {
175			return false
176		}
177		for _, allowed := range allowedHooks {
178			if allowed == hookName {
179				return true
180			}
181		}
182		return false
183	}
